SELECT 
    log_id, product_id, change_type, quantity_before, quantity_change, quantity_after,
    operator, remark, created_at
FROM inventory_log
WHERE product_id = #{productId}
ORDER BY created_at DESC

    LIMIT #{limit}


    OFFSET #{offset}

SELECT COUNT(*)
FROM inventory_log
WHERE product_id = #{productId}

SELECT 
    il.log_id, il.product_id, il.change_type, il.quantity_before, il.quantity_change, il.quantity_after,
    il.operator, il.remark, il.created_at
FROM inventory_log il
LEFT JOIN product p ON il.product_id = p.product_id


        AND il.product_id = #{productId}


        AND il.change_type = #{changeType}


        AND (p.name ILIKE '%' || #{keyword} || '%' 
             OR p.code ILIKE '%' || #{keyword} || '%')


ORDER BY il.created_at DESC

    LIMIT #{limit}


    OFFSET #{offset}

SELECT COUNT(*) FROM inventory_log il LEFT JOIN product p ON il.product_id = p.product_id
AND il.product_id = #{productId}
AND il.change_type = #{changeType}
AND (p.name ILIKE '%' || #{keyword} || '%' OR p.code ILIKE '%' || #{keyword} || '%')
